CREATE TABLE public.whatsapp_ai_controls(company_id uuid PRIMARY KEY REFERENCES public.companies(id),enabled boolean NOT NULL DEFAULT false,instructions text NOT NULL DEFAULT '',paused_reason text,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.whatsapp_ai_controls TO authenticated; GRANT ALL ON public.whatsapp_ai_controls TO service_role;
ALTER TABLE public.whatsapp_ai_controls ENABLE ROW LEVEL SECURITY;
CREATE POLICY wa_ai_read ON public.whatsapp_ai_controls FOR SELECT TO authenticated USING(public.license_active() AND public.lead_workspace_active() AND public.is_company_member(auth.uid(),company_id));
CREATE OR REPLACE FUNCTION public.wa_ai_settings(_company uuid,_enabled boolean,_instructions text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.org_customer_admin(auth.uid(),_company) OR NOT public.license_active() THEN RAISE EXCEPTION 'Customer Admin required'; END IF; IF length(_instructions)>8000 THEN RAISE EXCEPTION 'Instructions too long'; END IF; IF _enabled THEN RAISE EXCEPTION 'Automatic replies are not implemented yet; suggestions are available'; END IF; INSERT INTO public.whatsapp_ai_controls(company_id,enabled,instructions) VALUES(_company,false,_instructions) ON CONFLICT(company_id) DO UPDATE SET instructions=EXCLUDED.instructions,enabled=false,updated_at=now(); END $$;
REVOKE ALL ON FUNCTION public.wa_ai_settings(uuid,boolean,text) FROM PUBLIC,anon; GRANT EXECUTE ON FUNCTION public.wa_ai_settings(uuid,boolean,text) TO authenticated;